query.base:
SET unmapped_fields = "nullify";
TS metrics-gcp.gke.otel-*
| WHERE resource.attributes.gcp.resource_type == "k8s_container"
    // Keep the non-evictable memory series (working set) and the unlabelled series (restart_count)
    AND (attributes.memory_type == "non-evictable" OR attributes.memory_type IS NULL)
// restart_count is a cumulative counter: INCREASE gives restarts in the rule window (needs 2+ samples per series).
// Peak memory against the limit is context only: near 1.0 next to restarts suggests OOM kills.
| STATS restarts = SUM(INCREASE(`metrics.kubernetes.io/container/restart_count`)),
        peak_memory_limit_utilization = MAX(MAX_OVER_TIME(`metrics.kubernetes.io/container/memory/limit_utilization`)),
        last_seen = MAX(@timestamp)
    BY resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster_name,
       resource.attributes.namespace_name, resource.attributes.pod_name, resource.attributes.container_name
// Newest container sample of each cluster, for the per-cluster freshness rule
| INLINE STATS cluster_newest = MAX(last_seen)
    BY resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster_name
// Kibana takes alert identity from the BY of the last STATS or INLINE STATS, so regroup per container
// (one row each already)
| STATS restarts = MAX(restarts), peak_memory_limit_utilization = MAX(peak_memory_limit_utilization),
        last_seen = MAX(last_seen), cluster_newest = MAX(cluster_newest)
    BY resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster_name,
       resource.attributes.namespace_name, resource.attributes.pod_name, resource.attributes.container_name
// INCREASE extrapolates to the window edges, so round to whole restarts
| EVAL restarts = ROUND(restarts)

breach.segment:
// Ignore containers that stopped reporting (deleted pods) more than 5 minutes before their cluster's newest sample
WHERE last_seen >= cluster_newest - 5 minutes
// Threshold: restarts in the rule window. CrashLoopBackOff caps the back-off at 5 minutes,
// so a container that keeps crashing restarts about 6 times in 30 minutes.
| WHERE restarts >= 3
| KEEP resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster_name,
       resource.attributes.namespace_name, resource.attributes.pod_name, resource.attributes.container_name,
       restarts, peak_memory_limit_utilization, last_seen
| SORT restarts DESC
